<?php
use Agent\Views as V;
$user = $state['user'];
$tabs = ['appearance' => 'Appearance', 'personas' => 'Personas', 'knowledge' => 'Memory'];
if ($user['is_admin']) $tabs += ['models' => 'Models', 'access' => 'People & tools', 'services' => 'Services'];
if (!isset($tabs[$tab])) $tab = 'appearance';
?>
<header class="topbar"><div class="title">Settings</div><div class="top-actions"><a class="button" href="<?=V::url($current ? '?thread=' . $current['thread']['id'] : '')?>">Back to chat</a><?php if ($state['auth_mode'] === 'standalone'): ?><button data-action="logout">Sign out</button><?php endif; ?></div></header>
<div class="settings-content"><div class="settings-inner"><h1>Make it yours.</h1><p class="muted">A thoughtful workspace, on your terms.</p><nav class="settings-nav"><?php foreach ($tabs as $key => $label): ?><a class="button <?=$tab === $key ? 'active' : ''?>" href="<?=V::url('?view=settings&tab=' . $key)?>"><?=$label?></a><?php endforeach; ?></nav><div id="settings-page" data-settings-page="<?=V::h($tab)?>">
<?php if ($tab === 'appearance'): ?>
<section class="card"><h2>A little light, or a little dark?</h2><p class="muted">Choose the look that feels comfortable. Saved in this browser for your account.</p><div class="row"><button data-theme-choice="light" aria-pressed="<?=$state['preferences']['theme'] === 'light' ? 'true' : 'false'?>">Light</button><button data-theme-choice="dark" aria-pressed="<?=$state['preferences']['theme'] === 'dark' ? 'true' : 'false'?>">Dark</button></div></section>
<section class="card"><h2>Your little sidekick</h2><p class="muted">A character, not a voice. Quiet company with a few expressions up its sleeve.</p><div class="avatar-options">
<?php foreach (['terminal' => 'Little terminal', 'sprout' => 'Sprout'] as $name => $label): ?><button class="avatar-option <?=(isset($state['preferences']['avatar']) ? $state['preferences']['avatar'] : 'terminal') === $name ? 'active' : ''?>" data-avatar-choice="<?=$name?>"><?=V::avatar($state, '', $name)?><?=$label?></button><?php endforeach; ?>
</div><p class="hint">Your avatar is independent of your persona. Reduced-motion preferences are respected.</p></section>
<?php elseif ($tab === 'personas'): ?>
<section class="card"><div class="card-head"><h2>Personas</h2><button class="primary" data-dialog="persona">New persona</button></div><p class="hint">Selecting a persona copies its prompt into a conversation. Later changes do not rewrite existing conversations.</p>
<?php foreach ($state['personas'] as $p): ?><div class="card"><div class="card-head"><div><h3><?=V::h($p['name'])?></h3><span class="badge neutral"><?=V::h(($p['is_default'] ? 'Curated · ' : '') . $p['visibility'])?></span></div><?php if ($p['owner_id'] === $user['id'] || ($user['is_admin'] && $p['visibility'] !== 'private')): ?><button data-dialog="persona" data-id="<?=$p['id']?>">Edit</button><?php endif; ?></div><p><?=nl2br(V::h($p['prompt']))?></p></div><?php endforeach; ?></section>
<?php elseif ($tab === 'knowledge'): $claims = Agent\Knowledge::recall(isset($_GET['q']) ? $_GET['q'] : '', $user['id'], null, 50); ?>
<section class="card"><h2>Source-backed memory</h2><p class="hint">Every conversation is indexed. The Memory tool additionally permits cross-thread retrieval and maintaining durable knowledge.</p><form method="get" class="row"><input type="hidden" name="view" value="settings"><input type="hidden" name="tab" value="knowledge"><input name="q" value="<?=V::h(isset($_GET['q']) ? $_GET['q'] : '')?>" placeholder="Search facts, preferences, relationships…" aria-label="Search memory"><button>Search</button></form>
<?php foreach ($claims as $claim): ?><div class="card"><p><?=V::h($claim['content'])?></p><span class="badge neutral"><?=V::h($claim['visibility'])?></span><small class="muted"> Sources: <?php foreach ($claim['sources'] as $source): ?><a href="<?=V::url('?thread=' . $claim['thread_id'] . '#message-' . $source)?>"><?=$source?></a> <?php endforeach; ?></small><?php if ($claim['owner_id'] === $user['id']): ?><div class="row end"><button data-dialog="claim" data-id="<?=$claim['id']?>">Edit</button><button data-forget="<?=$claim['id']?>">Forget</button></div><?php endif; ?></div><?php endforeach; if (!$claims): ?><div class="empty">No matching memories yet.</div><?php endif; ?></section>
<?php elseif ($tab === 'models'): $registry = new Agent\Registry(); $profiles = $registry->profiles(); $models = $registry->models(); $endpoints = $registry->endpoints(); ?>
<section class="card"><div class="card-head"><div><h2>Model registry</h2><p class="hint" style="margin:8px 0 0"><?=count($endpoints)?> endpoints · <?=count($models)?> models · <?=count($profiles)?> profiles. Discovery never runs inference.</p></div><button data-dialog="profile">Custom profile</button></div>
<form method="post" id="scan-form" class="grid"><label>LAN CIDRs<input name="cidr" value="<?=V::h(getenv('SCAN_CIDRS'))?>" placeholder="192.168.1.0/24"></label><label>Ports<input name="ports" value="<?=V::h(getenv('SCAN_PORTS'))?>"></label><div class="row"><label class="check-label"><input name="all" type="checkbox">All ports</label><button class="primary">Scan network</button></div></form><?php $activeScan = Agent\Database::row("SELECT id FROM operations WHERE type = 'scan' AND status IN ('queued','running') ORDER BY id DESC LIMIT 1"); ?><div id="scan-status" role="status" aria-live="polite" <?=$activeScan ? 'data-scan-active="' . V::h($activeScan['id']) . '"' : ''?>></div></section>
<section class="card"><div class="table-wrap"><table class="registry"><thead><tr><th>Profile / model</th><th>Status</th><th>Capabilities</th><th></th></tr></thead><tbody>
<?php foreach ($profiles as $p): $cfg = Agent\Config::profile($p); ?><tr><td><strong><?=V::h($p['name'])?></strong><small><?=V::h(isset($cfg['model']) ? $cfg['model'] : $cfg['body']['model'])?></small><small><?=V::h(isset($cfg['url']) ? $cfg['url'] : '')?></small></td><td><span class="badge <?=$p['enabled'] ? '' : 'neutral'?>"><?=$p['enabled'] ? 'Enabled' : 'Not enabled'?></span><small><?=$p['tested_at'] ? 'Tested ' . V::h($p['tested_at']) : 'Not tested'?></small></td><td><div class="capabilities"><?php foreach (Agent\Registry::CAPABILITIES as $key => $label): if ($p[$key]): ?><span class="badge"><?=$label?></span><?php endif; endforeach; ?></div></td><td><button data-dialog="profile" data-name="<?=V::h($p['name'])?>" data-profile-edit="<?=V::h($p['name'])?>">Configure</button></td></tr><?php endforeach; ?>
</tbody></table></div></section><section class="card"><h2>Discovered engines & models</h2>
<?php foreach ($endpoints as $endpoint): ?><details class="activity"><summary><?=V::h($endpoint['url'] . ' · ' . $endpoint['engine'] . ' · ' . $endpoint['status'])?></summary><pre><?=V::pretty($endpoint['metadata'])?></pre></details><?php endforeach; ?>
<?php foreach ($models as $model): ?><details class="activity"><summary><?=V::h($model['model'] . ' · ' . $model['status'])?></summary><pre><?=V::pretty($model['metadata'])?></pre></details><?php endforeach; ?></section>
<?php elseif ($tab === 'access'):
$users = Agent\Identity::users();
$teams = Agent\Mappings::rows('teams'); $memberships = Agent\Mappings::rows('memberships'); $permissions = Agent\Mappings::rows('permissions');
?>
<section class="card"><h2>People & teams</h2><div class="table-wrap"><table class="registry"><thead><tr><th>Person</th><th>Role</th><th>Teams</th></tr></thead><tbody><?php foreach ($users as $person): ?><tr><td><?=V::h($person['display_name'])?><small><?=V::h($person['username'])?></small></td><td><?=$person['is_admin'] ? 'Administrator' : 'Member'?></td><td><?php foreach ($memberships as $membership) if ($membership['user_id'] === $person['id']) foreach ($teams as $team) if ($team['id'] === $membership['team_id']) echo V::h($team['name']) . ' '; ?></td></tr><?php endforeach; ?></tbody></table></div>
<details class="activity"><summary>Create user or team</summary><div class="card"><form method="post" id="add-user" class="form-stack"><div class="grid"><label>Username<input name="username" required></label><label>Display name<input name="display_name" required></label></div><label>Password<input name="password" type="password" minlength="10" required></label><label class="check-label"><input type="checkbox" name="is_admin">Administrator</label><button>Create user</button></form><hr><form method="post" id="add-team" class="row"><input name="name" placeholder="Team name" required aria-label="New team name"><button>Create team</button></form></div></details>
<form method="post" id="membership-form" class="grid"><label>User<select name="user_id"><?php foreach ($users as $person): ?><option value="<?=V::h($person['id'])?>"><?=V::h($person['display_name'])?></option><?php endforeach; ?></select></label><label>Team<select name="team_id"><?php foreach ($teams as $team): ?><option value="<?=V::h($team['id'])?>"><?=V::h($team['name'])?></option><?php endforeach; ?></select></label><div class="row"><button name="operation" value="add">Add membership</button><button name="operation" value="remove">Remove membership</button></div></form></section>
<section class="card"><h2>Tool policy</h2><p class="hint">The administrator grants permission; the thread creator selects the tool. Both the creator and message sender must be permitted to use it.</p><form method="post" id="policy-form" class="form-stack"><div class="grid"><label>Scope<select name="scope"><option value="organization:*">Organization</option><?php foreach ($teams as $team): ?><option value="team:<?=V::h($team['id'])?>">Team · <?=V::h($team['name'])?></option><?php endforeach; foreach ($users as $person): ?><option value="user:<?=V::h($person['id'])?>">User · <?=V::h($person['display_name'])?></option><?php endforeach; ?></select></label><label>Tool<select name="tool"><?php foreach (Agent\Frontend::TOOLS as $tool): ?><option value="<?=V::h($tool)?>"><?=V::h(substr($tool, strrpos($tool, '\\') + 1))?></option><?php endforeach; ?></select></label></div><label>Permission<select name="allowed"><option value="true">Allow</option><option value="false">Deny</option></select></label><button class="primary">Save permission</button></form><div class="table-wrap"><table class="registry"><thead><tr><th>Scope</th><th>Tool</th><th>Permission</th></tr></thead><tbody><?php foreach ($permissions as $rule): ?><tr><td><?=V::h($rule['scope_type'] . ' · ' . $rule['scope_id'])?></td><td><?=V::h($rule['tool'])?></td><td><?=$rule['allowed'] ? 'Allow' : 'Deny'?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php elseif ($tab === 'services'): $services = []; foreach (['searxng', 'camoufox'] as $name) { try { $services[$name] = Agent\Config::service($name); } catch (Exception $e) { $services[$name] = ['error' => $e->getMessage()]; } } ?>
<section class="card"><h2>Self-hosted services</h2><p class="hint">Database settings override local JSON. Use token_env to refer to a secret environment variable.</p><form method="post" id="services-form" class="form-stack"><label>Service configuration<textarea class="json-editor" name="services" rows="15"><?=V::pretty($services)?></textarea></label><div id="services-error"></div><button class="primary">Save services</button></form></section>
<?php try { $parsers = Agent\AttachmentParser::configuration(); } catch (Exception $e) { $parsers = []; echo '<p class="hint">' . V::h($e->getMessage()) . '</p>'; } ?>
<section class="card"><h2>Attachment parsing</h2><p class="hint">Native model support comes first. Otherwise, map a MIME type, .extension, or wildcard to a parsing profile, for example <code>{"image/*": "local-vision"}</code>. Leave empty to use local converters. Disabled profiles are allowed here; they need not be selectable in chat.</p><form method="post" id="attachment-parsers-form" class="form-stack"><label>File types → profile names<textarea class="json-editor" name="parsers" rows="6"><?=V::pretty((object)$parsers)?></textarea></label><details class="activity"><summary>Available profile names</summary><ul><?php foreach ((new Agent\Registry())->profiles() as $profile): ?><li><?=V::h($profile['name'])?></li><?php endforeach; ?></ul></details><p class="hint">Local fallback: PDF text extraction, PDF page images for vision, English OCR for images/scanned PDFs, and DOCX/ODT text. PDF image/OCR conversion is limited to the first eight pages. Upload limit: <?=number_format(Agent\Attachments::maxBytes() / 1048576, 1)?> MiB per file, eight files per message.</p><button class="primary">Save parsing profiles</button></form></section>
<?php endif; ?>
</div></div></div>
